package pe.vichaval.gestionriego.notificacion.service;
import java.time.OffsetDateTime; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import pe.vichaval.gestionriego.notificacion.repository.NotificacionRepository;
@Service public class MantenimientoNotificacionesService {private final NotificacionRepository r;private final int leidas,archivadas;public MantenimientoNotificacionesService(NotificacionRepository r,@Value("${vichayal.notifications.read-retention-days:180}")int l,@Value("${vichayal.notifications.archived-retention-days:90}")int a){if(l<30||a<30)throw new IllegalArgumentException("La retención mínima es 30 días");this.r=r;leidas=l;archivadas=a;}@Scheduled(cron="${vichayal.notifications.cleanup-cron:0 45 2 * * *}",zone="America/Lima")@Transactional public long depurar(){return r.deleteByEstadoAndFechaArchivadoBefore("ARCHIVADA",OffsetDateTime.now().minusDays(archivadas))+r.deleteByEstadoAndFechaLecturaBefore("LEIDA",OffsetDateTime.now().minusDays(leidas));}}
